-- Spanish (Latin America) (esMX): the guide forever/reputation/bloodsail-buccaneers (forever/reputation/bloodsail-buccaneers.guide).
-- Written by `forge i18n guides sync esMX`, which keeps every translation (docs/TRANSLATING.md, "Guide texts").
-- Translate the right-hand sides; "" shows the English. Keep each {kind:id} as it is: the game shows its
-- name there in Spanish (Latin America) (the English is listed above the line). A name the English has in the plural, as words,
-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in Spanish (Latin America) words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	["Bloodsail Buccaneers Reputation"] = "Reputación con los Bucaneros Velasangre",
	-- {item:10030} Admiral's Hat · {area:35} Booty Bay
	["The pirate outfit and the {item:10030}, bought with a war against {area:35} and every goblin town."] = "El atuendo pirata y el {item:10030}, comprados con una guerra contra {area:35} y todos los pueblos goblin.",

	-- Step 1: Before you start
	["Before you start"] = "Antes de empezar",
	-- {area:35} Booty Bay · {area:976} Gadgetzan · {area:392} Ratchet · {area:2255} Everlook
	["Bloodsail standing goes up only by killing the people of {area:35}, and every kill costs you {area:35} 125 and the other goblin towns ({area:976}, {area:392}, {area:2255}, and in Forever likely Powderfuse) about 62 each. After the Bruisers this guide asks for, every goblin town is Hated: their guards attack you, and you lose their flight masters, inns, vendors and {area:976}'s and {area:2255}'s auction houses. Getting back takes longer than getting here (last step). Fly in, bind elsewhere, and do your goblin-town business first. The outfit and the hat need only Friendly; past that Bloodsail has nothing to give. {area:35}'s guards are not your enemies yet: tick At War for {area:35} in your reputation panel, then attack."] = "La reputación Velasangre solo sube matando a la gente de {area:35}, y cada muerte te cuesta 125 con {area:35} y unos 62 con cada uno de los otros pueblos goblin ({area:976}, {area:392}, {area:2255} y, en Forever, probablemente Polvorín). Después de los matones que pide esta guía, todos los pueblos goblin quedan en Odiado: sus guardias te atacan, y pierdes sus maestros de vuelo, posadas, vendedores y las casas de subastas de {area:976} y {area:2255}. Volver toma más que llegar aquí (último paso). Llega volando, fija tu piedra de hogar en otro lado y haz primero tus asuntos en los pueblos goblin. El atuendo y el sombrero solo piden Amistoso; más allá, los Velasangre no tienen nada que dar. Los guardias de {area:35} todavía no son tus enemigos: marca En guerra con {area:35} en tu panel de reputación, y luego ataca.",

	-- Step 2: Booty Bay Bruisers to Neutral
	-- plural, as words: Booty Bay Bruisers = {npc:4624} Booty Bay Bruiser
	["Booty Bay Bruisers to Neutral"] = "Matones de Bahía del Botín hasta Neutral",
	-- {area:35} Booty Bay · {area:327} Faldir's Cove · {zone:1417} Arathi Highlands
	["Look at your Bloodsail bar first. A new character starts Hated, 500 short of Hostile: 260 Bruisers to Neutral, at 25 each. But every {area:35} quest you did while leveling took five times its {area:35} reward off Bloodsail (An OOX of Your Own, Stranglethorn Fever and Facing Negolash 1,000 each), and every Bloodsail pirate you killed 25 more: after {area:35}'s quests you sit near the bottom of Hated, up to 1,680 Bruisers from Neutral. Divide what the bar still lacks to Hostile, plus 6,000, by 25. Bruisers (level 57) hit hard, net you and knock you back, and new ones come when a goblin calls for help. Fight on the path that turns left from the tunnel up to the blacksmith's house: two Bruisers patrol it and rarely meet. Once they are down, step into the house (or hit one of the goblins inside) and a fresh Bruiser comes running. Players manage 30 to 40 an hour. {area:35} is Hated after about 53 Bruisers from a fresh Neutral 500. At the New Year celebration the town's goblins are drunk and do not fight back. The Blackwater crew at {area:327} in the {zone:1417} (level 37-40) are easier but pay only 5 each. Do not kill Bloodsail pirates: each costs 25."] = "Mira primero tu barra Velasangre. Un personaje nuevo empieza en Odiado, a 500 de Hostil: 260 matones hasta Neutral, a 25 cada uno. Pero cada misión de {area:35} que hiciste al subir de nivel le quitó a los Velasangre cinco veces su recompensa con {area:35} (Un OOX para ti, Fiebre de Tuercespina y Enfrentarse a Negolash, 1.000 cada una), y cada pirata Velasangre que mataste 25 más: después de las misiones de {area:35} estás cerca del fondo de Odiado, hasta a 1.680 matones de Neutral. Divide lo que le falta a la barra hasta Hostil, más 6.000, entre 25. Los matones (nivel 57) pegan fuerte, te lanzan redes y te empujan, y llegan nuevos cuando un goblin pide ayuda. Pelea en el camino que dobla a la izquierda desde el túnel hacia la casa del herrero: dos matones lo patrullan y casi nunca se cruzan. Cuando caigan, entra a la casa (o golpea a uno de los goblins de adentro) y llega corriendo un matón nuevo. Los jugadores hacen de 30 a 40 por hora. {area:35} queda en Odiado tras unos 53 matones desde un Neutral 500 recién empezado. En la celebración de Año Nuevo los goblins del pueblo están borrachos y no se defienden. La tripulación de Aguasnegras en {area:327}, en {zone:1417} (nivel 37-40), es más fácil pero paga solo 5 cada uno. No mates piratas Velasangre: cada uno cuesta 25.",
	["the path to the smithy"] = "el camino a la herrería",

	-- Step 3: Dressing the Part
	-- {npc:2546} Fleet Master Firallon · {area:1757} Crimson Veil · {area:35} Booty Bay · {item:22746} Buccaneer's Uniform · {item:22742} Bloodsail Shirt
	["At Neutral the Bloodsail crew stop attacking you. {npc:2546} is aboard the {area:1757}, the pirate ship anchored south of {area:35}, on its middle deck. Swim out; take the quest and hand it in on the spot for the {item:22746}: the {item:22742}, Sash, Pants and Boots."] = "En Neutral la tripulación Velasangre deja de atacarte. {npc:2546} está a bordo del {area:1757}, el barco pirata anclado al sur de {area:35}, en su cubierta del medio. Llega nadando; toma la misión y entrégala ahí mismo por el {item:22746}: el {item:22742}, la faja, los pantalones y las botas.",
	-- {npc:2546} Fleet Master Firallon · {item:22746} Buccaneer's Uniform
	["{npc:2546}: the {item:22746}"] = "{npc:2546}: el {item:22746}",

	-- Step 4: Bruisers to Friendly
	["Bruisers to Friendly"] = "Matones hasta Amistoso",
	["Neutral to Friendly is 3,000 more: 120 Bruisers. Friendly is the last standing that unlocks anything."] = "De Neutral a Amistoso son 3.000 más: 120 matones. Amistoso es la última reputación que desbloquea algo.",

	-- Step 5: Avast Ye, Scallywag
	-- {area:35} Booty Bay
	["\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of {area:35}. {area:35} players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while {area:35} is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with {area:35}."] = "\"El Guapo\" Duncan, un pirata Velasangre, está en la playa al norte de {area:35}. Los jugadores de {area:35} lo matan para una misión: si no está, espéralo. Tiene una misión para ti desde el nivel 55, mientras {area:35} esté por debajo de Neutral; queda hecha cuando estés en Amistoso con los Velasangre y en Odiado con {area:35}.",
	-- {npc:2546} Fleet Master Firallon · {area:1757} Crimson Veil
	["{npc:2546}, on the {area:1757}: 25"] = "{npc:2546}, en el {area:1757}: 25",

	-- Step 6: Avast Ye, Admiral!
	-- {npc:2496} Baron Revilgaz · {npc:2487} Fleet Master Seahorn · {area:35} Booty Bay
	["{npc:2496} and {npc:2487} stand on the top floor of the {area:35} inn, out on the balcony. Both are level 60 and Bruisers come to their aid: clear the stairs first and pull them one at a time. They come back, so a friend can kill them too."] = "{npc:2496} y {npc:2487} están en el último piso de la posada de {area:35}, afuera en el balcón. Los dos son de nivel 60 y los matones acuden en su ayuda: despeja primero las escaleras y atráelos de uno en uno. Reaparecen, así que un amigo también puede matarlos.",

	-- Step 7: The Admiral's Hat
	-- {item:10030} Admiral's Hat
	["The {item:10030}"] = "El {item:10030}",
	-- {item:12185} Bloodsail Admiral's Hat · {area:35} Booty Bay · {zone:1418} Badlands
	["Back to Firallon for the {item:12185} (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less {area:35}. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the {zone:1418}, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached."] = "De vuelta con Firallon por el {item:12185} (en Classic su uso invoca un loro en tu hombro): 200 más con los Velasangre y 1.000 menos con {area:35}. Los matones pagan 25 solo hasta el final de Honorable, y Jazzrik, un goblin solitario de {zone:1418}, 5 hasta el final de Reverenciado; no queda ninguna misión, así que no se puede llegar a Exaltado.",

	-- Step 8: The way back
	["The way back"] = "El camino de vuelta",
	-- {area:392} Ratchet · {area:35} Booty Bay · {area:976} Gadgetzan · {area:2255} Everlook · {npc:14637} Zorbin Fandazzle · {zone:1444} Feralas
	["Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside {area:392}, {area:35}, {area:976} and {area:2255}, so the climb back is the Cartel's own: {npc:14637} in {zone:1444} serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give {area:35} 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did."] = "Todos los pueblos goblin están ahora en Odiado. Los datos de misiones de Forever quitan la reputación de los pueblos de las cuatro misiones goblin de reparación de fuera de {area:392}, {area:35}, {area:976} y {area:2255}, así que la vuelta es la del propio Cártel: {npc:14637}, en {zone:1444}, atiende a todos, y sus misiones de gigantes electrocutados pagan 25 a cada pueblo a la vez; los piratas Velasangre dan 5 cada uno con {area:35} hasta el final de Neutral (y cuestan 25 con los Velasangre); los piratas Mares del Sur y la Compañía de Ventura en Tuercespina dan 5 cada uno a los pueblos. La guía del Cártel Bonvapor tiene los detalles. Cuenta con que tome más que la guerra.",
	-- {npc:14637} Zorbin Fandazzle
	["{npc:14637}: Zapped Giants, open to the Hated"] = "{npc:14637}: gigantes electrocutados, abierto a quienes están en Odiado",
}
